play": "5 490 €", "payment_options": ["2 × 2 950 €", "3 × 1 990 €", "4 × 1 550 €"]}, {"name": "Starter Solo", "price": 1490, "description": "Seulement après un non budget sur Starter en 4 fois et après avoir proposé l'acompte de 1 490 € : session de départ avec un coach, session questions générales hebdomadaire, tous les modules, communauté, point à 4 mois ; pas de messagerie coach, de flash coaching, de roleplay, de sessions vente et pub ni d'expert pub. Passage à Starter à tout moment en payant la différence.", "price_display": "1 490 €", "payment_options": ["4 × 397 €"]}], "payment_options": ["Carte bancaire : tout se paie par carte", "Virement seulement après deux tentatives par carte échouées"], "roi_calculation": {"investment": 3000, "payback_period": null, "expected_return": "3 élèves × une offre à plus de 500 € = 1 500 € le premier mois (ordre de grandeur de ceux qui bossent, pas une promesse)"}, "financing_options": [{"id": "comptant", "name": "3 000 € en une fois", "coverage": "100 % de l'accompagnement", "description": "Paiement par carte en une fois", "eligibility": "Tous", "result_for_prospect": "3 000 €"}, {"id": "2-fois", "name": "2 × 1 600 €", "coverage": "100 % de l'accompagnement", "description": "Paiement en 2 fois par carte", "eligibility": "Tous", "result_for_prospect": "3 200 € au total : une facilité, pas une remise"}, {"id": "3-fois", "name": "3 × 1 100 €", "coverage": "100 % de l'accompagnement", "description": "Paiement en 3 fois par carte", "eligibility": "Tous", "result_for_prospect": "3 300 € au total"}, {"id": "4-fois", "name": "4 × 850 €", "coverage": "100 % de l'accompagnement", "description": "Paiement en 4 fois par carte", "eligibility": "Tous", "result_for_prospect": "3 400 € au total"}, {"id": "2-fois-sans-frais", "name": "2 × 1 500 € sans frais", "coverage": "100 % de l'accompagnement", "description": "Lien de paiement en 2 fois sans frais", "eligibility": "Seulement quand la personne veut payer en une fois et que le plafond de s