ut": ["Si au bout de 4 mois j'ai rien, je récupère mes sous ?", "Je suis prof titulaire, j'ai le droit ?", "La pub, c'est vous qui la faites pour moi ?", "Il se passe quoi après les 4 mois ?", "Le coach, il me répond en combien de temps ?", "Il y a des frais cachés, des modules à débloquer en plus ?"], "key_numbers_to_remember": [{"number": "4 mois", "context": "durée de l'accompagnement", "full_phrase": "L'accompagnement dure 4 mois"}, {"number": "250", "context": "profs dans la communauté", "full_phrase": "Il y a 250 profs dans la communauté"}, {"number": "4 500 h", "context": "cours donnés par Antoine", "full_phrase": "Antoine a donné plus de 4 500 heures de cours particuliers"}, {"number": "4 h", "context": "temps par semaine", "full_phrase": "Il faut compter 4 heures par semaine minimum"}]}}, "sources": [{"note": "Offre écrite à la main d'après la fiche mémo et les cas de l'Académie sales LNP ; pas de texte à ré-analyser.", "type": "txt", "filename": "app/training/academie_contenu.json"}], "fingerprint": "lnp:accompagnement-les-nouveaux-profs", "status": "ready", "error": null, "archived": false, "created_by": null, "created_at": "2026-11-11T11:23:37.780628+00:00", "updated_at": "2026-11-11T12:22:56.074+00:00"}$lnp$::jsonb) r), updated_at = now() where t.id = 'b1a7c0de-0000-4000-8000-000000000057';

